-- Images CueFlow stores itself: uploaded by a reviewer or generated by an image connector.
-- Served at /media/{id}; posts reference them as "/media/{id}" in media_urls.
CREATE TABLE media (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mime_type    VARCHAR(64) NOT NULL,
    data         BYTEA NOT NULL,
    size_bytes   INTEGER NOT NULL,
    source       VARCHAR(16) NOT NULL,   -- upload | generated
    prompt       TEXT NOT NULL DEFAULT '',
    connector_id UUID REFERENCES connectors(id) ON DELETE SET NULL,
    created_by   VARCHAR(64) NOT NULL DEFAULT 'human',  -- human | agent slug
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_media_created ON media(created_at DESC);
